from django.core.signing import TimestampSigner, BadSignature, SignatureExpired
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import WorkspaceShare, Workspace

class ClaimWorkspaceShareView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        signed_token = request.data.get('share_token')
        if not signed_token:
            return Response({'error': 'Token required'}, status=status.HTTP_400_BAD_REQUEST)

        # Segregate salt and verify target recipient email match with max age
        signer = TimestampSigner(salt='workspace-member-invite-v1')
        try:
            token_payload = signer.unsign_object(signed_token, max_age=172800)
            workspace_id = token_payload.get('workspace_id')
            invitee_email = token_payload.get('invitee_email')
        except (BadSignature, SignatureExpired):
            return Response({'error': 'Invalid or expired invitation token'}, status=status.HTTP_400_BAD_REQUEST)

        if request.user.email.lower() != invitee_email.lower():
            return Response({'error': 'Invitation was issued to another email'}, status=status.HTTP_403_FORBIDDEN)

        workspace = Workspace.objects.get(pk=workspace_id)
        workspace.members.add(request.user)
        return Response({'status': 'Joined workspace', 'workspace': workspace.name})
